import React from 'react';
import { Link } from 'react-scroll'; // Import Link from react-scroll

const Resume = () => {
  return (
    <div id="resume" className="section">
      <h1>Resume</h1>
      <p>Here's a glimpse of my professional journey. Feel free to download my full resume for a more detailed overview.</p>

      {/* Embedding the resume PDF */}
      <object
        data="/../../assets/Resume.pdf" // Replace with the actual path to your resume PDF file
        type="application/pdf"
        width="100%"
        height="600px" // Adjust the height as needed
      >
        <p>Your browser does not support PDFs. Please download the PDF to view it: <a href="../../assets/Resume.pdf">Download PDF</a>.</p>
      </object>

      {/* Download link for the resume */}
      <a href="../../assets/Resume.pdf" download="Resume.pdf" className="download-link">
        Download CV
      </a>

      <Link to="home" smooth={true} duration={500}>Back to Home</Link>
    </div>
  );
};

export default Resume;
